entries[389406] = { ["name"] = "Titanversetztes Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nSie werden manchmal von kleinen Titanenforschungskonstrukten ermächtigt. Glücklicherweise tendieren sie dazu, ihre Stärkung dem zu gewähren, der das Vorkommen abbaut, statt sich zur Wehr zu setzen.\n\nIhr erhaltet beim Abbauen den folgenden Effekt:\n\nErleuchtetes Potenzial :\nErhöht die Geschwindigkeit um 15%. Außerdem werden die Sekundärwerte von auf titanenberührte Vorkommen spezialisierten Sammlern um 3% erhöht." }
entries[389407] = { ["name"] = "Wilde Rachfeder", ["text"] = "Sofort\nEure Schadenszauber haben eine Chance, einen Seelensucherpfeil auf Euer Ziel zu verschießen, der dem ersten getroffenen Gegner 0 Schattenschaden im Verlauf von 1 Min. zufügt. Falls das Ziel stirbt, während es mit dem Effekt belegt ist, verschießen Eure nächsten Schadenszauber einen Pfeil." }
entries[389408] = { ["name"] = "Im'bunatas Zorn", ["text"] = "Unbegrenzte Reichweite\nSofort 10 sek. Abklingzeit\nRuft den Zorn von Im'bunata herbei!" }
entries[389409] = { ["name"] = "Urdrakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nSie sind manchmal von den Urelementen berührt und können zusätzliche tobende Elemente enthalten, die beim Abbauen entdeckt werden.\n\nDie Spezialisierung auf Urvorkommen gewährt beim Abbauen den folgenden Effekt:\n\nExplosive Elemente :\nErhöht die Abklingzeitverringerung von 'Überladung' um 30%. Spezialisierte Bergarbeiter haben eine Chance, mit ihren Zaubern und Fähigkeiten Bonuselementarschaden zu verursachen. Hält 2 Min. lang an." }
entries[389411] = { ["name"] = "Wachsende Kristalle" }
entries[389412] = { ["name"] = "Blinder Ansturm", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nNezascar der Blinde stürmt zur Position eines Spielercharakters, überrennt alle Spielercharaktere auf seinem Weg, fügt ihnen 30 körperlichen Schaden zu und betäubt sie für 5 Sek." }
entries[389413] = { ["name"] = "Gehärtetes Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nSie werden manchmal von einer zusätzlichen dicken Steinschicht bedeckt, wodurch der Abbau der in ihnen enthaltenen, wertvollen Erze erschwert wird.\n\nDie Spezialisierung auf gehärtete Vorkommen gewährt beim Abbauen den folgenden Effekt:\n\nGehärtete Haut :\nVerringert den erlittenen Schaden um 5%. Hält 2 Min. lang an." }
entries[389418] = { ["name"] = "Untersuchen" }
entries[389420] = { ["name"] = "Wutentbranntes Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nDieses Vorkommen ist in heftig umkämpften Gebieten zu finden und der Zorn der Kämpfenden soll den Überlebenden, die es irgendwann für sich beanspruchen, magische Effekte gewähren.\n\nIhr erhaltet beim Abbauen den folgenden Effekt:\n\nFuror des Kampfes :\nWenn Ihr gegnerische Spielercharaktere tötet, habt Ihr eine Chance, tobende Zorneskraft zu erhalten. Hält 2 Min. lang an.\n\nWeiteres Abbauen oder Kräutersammeln verlängert die Dauer." }
