entries[389443] = { ["name"] = "Läuternde Druckwelle", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nDas Nullifikationsgerät fügt einem zufälligen Ziel beim Treffer 969780 Arkanschaden und 10 Sek. lang alle 2 Sek. zusätzlich 484890 Arkanschaden zu. Dieser Effekt ist stapelbar." }
