entries[389448] = { ["name"] = "Tötungshiebe", ["text"] = "Nahkampfreichweite\nSofort\nWährend 'Raubtierhiebe' aktiv ist, trifft 'Tötungsbefehl' nun auch Gegner in der Nähe und fügt ihnen Schaden in Höhe von 80% des verursachten Schadens zu. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
