entries[389458] = { ["name"] = "Drakoniumflöz", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet. Flöze sind unglaublich seltene Ablagerungen, die man nur tief unter der Erde findet. Dafür erweisen sie sich für den glücklichen Höhlenforscher, der sie entdeckt, als äußerst ergiebig." }
entries[389459] = { ["name"] = "Geschmolzenes Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nSie sind manchmal in Flammen gehüllt, besonders in seismisch aktiven Gebieten. Ihre unerträgliche Hitze hält Anfänger oft davon ab, ihr reiches Vorkommen an tobendem Feuer abzubauen.\n\nDie Spezialisierung auf geschmolzene Vorkommen gewährt beim Abbauen den folgenden Effekt:\n\nGlühender Zorn :\nHüllt Euch in Flammen und lässt Eure Angreifer 1721 Feuerschaden erleiden. Hält 2 Min. lang an." }
entries[389460] = { ["name"] = "Reiches Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nReiche Vorkommen sind besonders ergiebig an Erzen und sicher eine Freude für jeden Bergarbeiter, der sie entdeckt." }
entries[389461] = { ["name"] = "Titanenberührtes Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nSie werden manchmal von kleinen Titanenforschungskonstrukten ermächtigt. Glücklicherweise tendieren sie dazu, ihre Stärkung dem zu gewähren, der das Vorkommen abbaut, statt sich zur Wehr zu setzen.\n\nIhr erhaltet beim Abbauen den folgenden Effekt:\n\nErleuchtetes Potenzial :\nErhöht die Geschwindigkeit um 15%. Außerdem werden die Sekundärwerte von auf titanenberührte Vorkommen spezialisierten Sammlern um 3% erhöht." }
entries[389462] = { ["name"] = "Urserevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nSie sind manchmal von den Urelementen berührt und können zusätzliche tobende Elemente enthalten, die beim Abbauen entdeckt werden.\n\nDie Spezialisierung auf Urvorkommen gewährt beim Abbauen den folgenden Effekt:\n\nExplosive Elemente :\nErhöht die Abklingzeitverringerung von 'Überladung' um 30%. Spezialisierte Bergarbeiter haben eine Chance, mit ihren Zaubern und Fähigkeiten Bonuselementarschaden zu verursachen. Hält 2 Min. lang an." }
entries[389463] = { ["name"] = "Gehärtetes Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nSie werden manchmal von einer zusätzlichen dicken Steinschicht bedeckt, wodurch der Abbau der in ihnen enthaltenen, wertvollen Erze erschwert wird.\n\nDie Spezialisierung auf gehärtete Vorkommen gewährt beim Abbauen den folgenden Effekt:\n\nGehärtete Haut :\nVerringert den erlittenen Schaden um 5%. Hält 2 Min. lang an." }
entries[389464] = { ["name"] = "Wutentbranntes Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nDieses Vorkommen ist in heftig umkämpften Gebieten zu finden und der Zorn der Kämpfenden soll den Überlebenden, die es irgendwann für sich beanspruchen, magische Effekte gewähren.\n\nIhr erhaltet beim Abbauen den folgenden Effekt:\n\nFuror des Kampfes :\nWenn Ihr gegnerische Spielercharaktere tötet, habt Ihr eine Chance, tobende Zorneskraft zu erhalten. Hält 2 Min. lang an.\n\nWeiteres Abbauen oder Kräutersammeln verlängert die Dauer." }
entries[389465] = { ["name"] = "Serevitflöz", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt. Flöze sind unglaublich seltene Ablagerungen, die man nur tief unter der Erde findet. Dafür erweisen sie sich für den glücklichen Höhlenforscher, der sie entdeckt, als äußerst ergiebig." }
