entries[389520] = { ["name"] = "Saat ausbrüten", ["text"] = "Unbegrenzte Reichweite\nSofort\nDiurnas fürsorgliche Bemühungen mit 'Schnelles Ausbrüten' laden Spielercharaktere innerhalb von 50 Metern auf und verursachen 30 Sek. lang pro Sekunde 1 Naturschaden. Dieser Effekt ist stapelbar, tötet Ziele bei über 4 Anwendungen sofort und lässt an der Position des Opfers einen Primalistenleutnant ausschlüpfen." }
