entries[389527] = { ["name"] = "Robuste Schuppen", ["text"] = "Sofort\nBeim Erleiden von Schaden besteht eine geringe Chance, dass Euch ein Schild gewährt wird, der 20 Sek. lang 3321 Schaden absorbiert und Eure Rüstung um 93 erhöht, solange der Schild besteht. Wird der Schild durchbrochen, explodiert er und verursacht 699 körperlichen Schaden, der unter allen Gegnern in der Nähe aufgeteilt wird." }
entries[389529] = { ["name"] = "Schwerer Hüpfer", ["text"] = "Sofort\nDer lauernde Oschi springt zur Position eines zufälligen Spielercharakters, fügt allen Spielercharakteren, die sich am Ort der Landung aufhalten, 158991 körperlichen Schaden zu und stößt sie zurück." }
