entries[389700] = { ["name"] = "Geschmolzenes Vorkommen überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Vorkommen dieser Art erzürnt einen darin lauernden tobenden Feuerelementar. Wenn Ihr ihn tötet, erhaltet Ihr tobendes Feuer als Bonus." }
entries[389701] = { ["name"] = "Gehärtetes Vorkommen überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Vorkommen dieser Art bewirkt, dass ein Teil der äußeren Schicht zu abbaubaren Brocken zerfällt, die tobende Erde als Bonus gewähren." }
entries[389702] = { ["name"] = "Ursprüngliches Vorkommen überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Vorkommen dieser Art gewährt Euch 3 Min. lang alle Segen, die beim Abbauen thematischer Vorkommen erhältlich sind, und zwar unabhängig von Euren Spezialisierungen." }
entries[389703] = { ["name"] = "Titanenvorkommen überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Vorkommen dieser Art bewirkt, dass sich ein Portal zu einem abbaubaren Vorkommen in der Nähe öffnet. Spezialisierte Bergarbeiter können nach abgeschlossener Arbeit am Zielort ein Rückkehrportal öffnen." }
entries[389704] = { ["name"] = "Wutentbranntes Vorkommen überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Vorkommen dieser Art verursacht eine verheerende Schockwelle, die Gegner in der Nähe zurückstößt und Euch selbst stärkt." }
