entries[389708] = { ["name"] = "Dunkelblicksegen", ["text"] = "Wenn Eure 'Dämonische Verwüstung' vollständig kanalisiert wurde, werden 15-30% ihrer Abklingzeit abgeschlossen und 15-30 Jähzorn erstattet." }
entries[389710] = { ["name"] = "Ausbrennende Welle", ["text"] = "100 Meter Reichweite\nSofort\nBindet Euch 20 Sek. lang an die Flamme, wodurch Eure Angriffe eine hohe Chance haben, Eure Stärke um 33 zu erhöhen. Bis zu 6-mal stapelbar. Wenn die Bindung vervollständigt wurde, sondert Ihr eine ausbrennende Welle ab, die abhängig von der Stärke Eurer Bindung bis zu 3775 Feuerschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird." }
entries[389711] = { ["name"] = "Seelentreiber", ["text"] = "Wenn Ihr beim Verschlingen eines Seelenfragments über Eure volle Gesundheit hinaus geheilt werden würdet, erhaltet Ihr stattdessen einen Schild in Höhe von bis zu maximal (Gesamtgesundheit * 10 / 100)." }
entries[389713] = { ["name"] = "Verzerrung", ["text"] = "40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nTeleportiert Euch zurück an den Ort, von dem aus Ihr zuletzt geblinzelt habt und heilt Euch um (20 / 100 * Gesamtgesundheit) Gesundheit. Kann nur innerhalb von 8 Sek. nach 'Blinzeln' verwendet werden." }
entries[389714] = { ["name"] = "Teleportationsleuchtfeuer", ["text"] = "Sofort\nTeleportiert Euch zurück an den Ort, von dem aus Ihr zuletzt geblinzelt habt und heilt Euch um (20 / 100 * Gesamtgesundheit) Gesundheit. Kann nur innerhalb von 8 Sek. nach 'Blinzeln' verwendet werden." }
