entries[389762] = { ["name"] = "Tieffrieren", ["text"] = "100 Meter Reichweite\nSofort\nBeim Erreichen von 100 Energie entfesselt Liskanoth ihre eisigen Kräfte und speit gefrorene Luft unter sich.\n\nAlle Spielercharaktere, die auf ihrem Weg getroffen werden, erleiden 99250 Frostschaden. Zusätzlich erleiden sie alle 1.5 Sek. 21835 Frostschaden und sind für 6 Sek. betäubt." }
