entries[389787] = { ["name"] = "Zeichen der Flamme", ["text"] = "Sofort\nPlatziert ein Zeichen der Flamme am Zielort, das sich nach 2 Sek. aktiviert.\n\nFügt allen vom Zeichen betroffenen Gegnern sofort (53.2827% der Angriffskraft) Feuer schaden sowie im Verlauf von 8 Sek. zusätzlich (133.385% der Angriffskraft) Feuer schaden zu.\n\nErzeugt 30 Jähzorn." }
entries[389788] = { ["name"] = "Die Schwachen ausbeuten", ["text"] = "Sofort\nDie Kriegsmeute wittert die Schwäche ihrer Beute und erhält einen Stapel von ' Räuberische Instinkte ' pro 10% der bei Spielercharakteren insgesamt fehlenden Gesundheit." }
entries[389789] = { ["name"] = "Klingensturm", ["text"] = "Sofort 1 min Abklingzeit\nBenötigt Nahkampfwaffe\nWerdet zu einem unaufhaltsamen Sturm der Zerstörung und fügt allen Gegnern in der Nähe im Verlauf von 4 Sek. [5 * (208.95% der Angriffskraft)%] körperlichen Schaden zu. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nIhr seid dabei gegen bewegungseinschränkende und Kontrollverlusteffekte immun, könnt aber defensive Fähigkeiten einsetzen und Angriffe vermeiden.\n\nErzeugt im Verlauf der Dauer 20 Wut." }
entries[389790] = { ["name"] = "Zephyrschmettern", ["text"] = "100 Meter Reichweite\nSofort\nDathea rammt ihre ermächtigte Faust mit einem Luftstoß in ihr derzeitiges Ziel, fügt ihm 353314 körperlichen Schaden zu und stößt es zurück.\n\nJeder Einschlag erhöht den erlittenen Schaden und den Rückstoß 55 Sek. lang um 50%. Dieser Effekt ist stapelbar." }
