entries[389878] = { ["name"] = "Fusionieren", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeim Erreichen des kolossalen Sturmungetüms, das ihn erschaffen hat, opfert sich der suchende Sturmling und heilt das kolossale Sturmungetüm um 5% seiner maximalen Gesundheit und erhöht seinen verursachten Schaden um 25%. Dieser Effekt ist stapelbar." }
entries[389879] = { ["name"] = "Koordinierte Tötung", ["text"] = "Sofort\nWährend 'Koordinierter Angriff' aktiv ist, ist die Abklingzeit von 'Lauffeuerbombe' um 25% verringert. 'Lauffeuerbombe' erzeugt beim Werfen 5 Fokus, die Abklingzeit von 'Tödlicher Schuss' ist um 25% verringert und 'Tödlicher Schuss' kann gegen jedes Ziel unabhängig von seiner aktuellen Gesundheit eingesetzt werden." }
