entries[390230] = { ["name"] = "Vulkanausbruch", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Elementar verpasst dem aktuellen Ziel mit geballter Faust einen Schmetterschlag, der dem Ziel 70 körperlichen Schaden zufügt und seinen erlittenen körperlichen Schaden 20 Sek. lang um 50% erhöht.\n\nAm Ort des Schmetterschlags erfolgen dann mehrere Vulkanausbrüche in einer Linie, die Spielercharakteren innerhalb von 4 Metern jeweils 45 Feuerschaden zufügen." }
